fused_post_cpp_source = """
#include &lt;hip/hip_runtime.h&gt;
#include &lt;hip_math.h&gt;
#include &lt;torch/extension.h&gt;

__global__ void fused_tanh_pool_sub_kernel(const float* __restrict__ in, float* __restrict__ out, float sub_val, int64_t N, int64_t C, int64_t Hi, int64_t Wi, int64_t Ho, int64_t Wo) {
    uint64_t gid = static_cast&lt;uint64_t&gt;(blockIdx.x) * blockDim.x + threadIdx.x;
    uint64_t size_out = static_cast&lt;uint64_t&gt;(N) * C * Ho * Wo;
    if (gid &gt;= size_out) return;
    int64_t n = static_cast&lt;int64_t&gt;(gid / (C * Ho * Wo));
    int64_t cc = static_cast&lt;int64_t&gt;((gid / (Ho * Wo)) % C);
    int64_t i = static_cast&lt;int64_t&gt;((gid / Wo) % Ho);
    int64_t j = static_cast&lt;int64_t&gt;(gid % Wo);
    float sum = 0.0f;
    int64_t base_h = i * 2LL;
    int64_t base_w = j * 2LL;
    for(int di = 0; di &lt; 2; ++di) {
        for(int dj = 0; dj &lt; 2; ++dj) {
            int64_t pi = base_h + di;
            int64_t pj = base_w + dj;
            int64_t idx_in = ((n * C + cc) * Hi + pi) * Wi + pj;
            sum += tanhf(in[idx_in]);
        }
    }
    out[gid] = sum * 0.25f - sub_val;
}

torch::Tensor fused_post_hip(torch::Tensor in, float sub_val) {
    TORCH_CHECK(in.dim() == 4, "Input must be 4D");
    auto N = in.size(0);
    auto C = in.size(1);
    auto Hi = in.size(2);
    auto Wi = in.size(3);
    auto Ho = Hi / 2;
    auto Wo = Wi / 2;
    auto out = torch::empty({N, C, Ho, Wo}, in.options());
    int64_t size_out = N * C * Ho * Wo;
    constexpr int64_t block_size = 256;
    int64_t num_blocks = (size_out + block_size - 1) / block_size;
    fused_tanh_pool_sub_kernel&lt;&lt;&lt;num_blocks, block_size&gt;&gt;&gt;(in.data_ptr&lt;float&gt;(), out.data_ptr&lt;float&gt;(), sub_val, N, C, Hi, Wi, Ho, Wo);
    return out;
}
"""

fused_post = load_inline(
    name="fused_post",
    cpp_sources=fused_post_cpp_source,
    functions=["fused_post_hip"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, subtract1_value, subtract2_value, kernel_size_pool):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.conv.bias.data -= subtract1_value
        self.subtract2_value = subtract2_value
        self.fused_post = fused_post

    def forward(self, x):
        x = self.conv(x)
        x = self.fused_post.fused_post_hip(x, self.subtract2_value)
        return x

