conv2d_cpp_source = """
#include &lt;hip/hip_runtime.h&gt;

__global__ void conv2d_kernel(const float* input, const float* weight, const float* bias, float* output,
                              int N, int Cin, int Cout, int H, int W, int K, int Hout, int Wout) {
  const int wout = blockIdx.x * blockDim.x + threadIdx.x;
  const int hout = blockIdx.y * blockDim.y + threadIdx.y;
  const int bco = blockIdx.z;
  const int n = bco / Cout;
  const int cout = bco % Cout;

  if (hout &lt; Hout &amp;&amp; wout &lt; Wout &amp;&amp; n &lt; N) {
    float sum = bias[cout];
    for (int cin = 0; cin &lt; Cin; ++cin) {
      for (int dy = 0; dy &lt; K; ++dy) {
        int hin = hout + dy;
        for (int dx = 0; dx &lt; K; ++dx) {
          int win = wout + dx;
          sum += input[n * (Cin * H * W) + cin * (H * W) + hin * W + win] *
                 weight[cout * (Cin * K * K) + cin * (K * K) + dy * K + dx];
        }
      }
    }
    output[n * (Cout * Hout * Wout) + cout * (Hout * Wout) + hout * Wout + wout] = sum;
  }
}

torch::Tensor conv2d_hip(torch::Tensor input, torch::Tensor weight, torch::Tensor bias, int K) {
  auto N = input.size(0);
  auto Cin = input.size(1);
  auto H = input.size(2);
  auto W = input.size(3);
  auto Cout = weight.size(0);
  auto Hout = H - K + 1;
  auto Wout = W - K + 1;
  auto output = torch::empty({N, Cout, Hout, Wout}, input.options());
  const int TX = 16;
  const int TY = 16;
  dim3 block(TX, TY);
  dim3 grid((Wout + TX - 1) / TX, (Hout + TY - 1) / TY, N * Cout);
  conv2d_kernel&lt;&lt;&lt;grid, block&gt;&gt;&gt;(input.data_ptr&lt;float&gt;(), weight.data_ptr&lt;float&gt;(), bias.data_ptr&lt;float&gt;(), output.data_ptr&lt;float&gt;(), N, Cin, Cout, H, W, K, Hout, Wout);
  return output;
}
"""

custom_conv = load_inline(
    name="conv2d",
    cpp_sources=conv2d_cpp_source,
    functions=["conv2d_hip"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, scaling_factor):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.bn = nn.BatchNorm2d(out_channels)
        self.scaling_factor = scaling_factor
        self.custom_conv = custom_conv

    def forward(self, x):
        weight = self.conv.weight
        bias = self.conv.bias
        conv_out = self.custom_conv.conv2d_hip(x, weight, bias, kernel_size)
        x = self.bn(conv_out)
        return x * self.scaling_factor

import os
os.environ["CXX"] = "hipcc"
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp = """
#include &lt;hip/hip_runtime.h&gt;
#include &lt;cmath&gt;

__device__ float gelu_fp32(float x) {
    float x2 = x * x;
    float x3 = x2 * x;
    float d = tanhf(0.7978845608f * (x + 0.044715f * x3));
    return 0.5f * x * (1.0f + d);
}

__global__ void fused_matmul_bias_div_gelu_kernel(
    const float* x, const float* w, const float* b, float div, float* out,
    int B, int I, int O
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int N = B * O;
    if (idx &gt;= N) return;
    int batch = idx / O;
    int row = idx % O;
    float acc = 0.0f;
    for (int col = 0; col &lt; I; ++col) {
        acc += x[batch * I + col] * w[row * I + col];
    }
    acc += b[row];
    float val = acc / div;
    out[batch * O + row] = gelu_fp32(val);
}

torch::Tensor fused_linear_hip(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    torch::Tensor divisor
) {
    int64_t B = x.size(0);
    int64_t I = x.size(1);
    int64_t O = weight.size(0);
    auto out = torch::zeros({B, O}, x.options());
    float divv = divisor.item&lt;float&gt;();
    const int threads = 256;
    const int blocks = (B * O + threads - 1) / threads;
    fused_matmul_bias_div_gelu_kernel&lt;&lt;&lt;blocks, threads&gt;&gt;&gt; (
        x.data_ptr&lt;float&gt;(),
        weight.data_ptr&lt;float&gt;(),
        bias.data_ptr&lt;float&gt;(),
        divv,
        out.data_ptr&lt;float&gt;(),
        B, I, O
    );
    return out;
}
"""

fused_module = load_inline(
    name="fused",
    cpp_sources=cpp,
    functions=["fused_linear_hip"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self, input_size, output_size, divisor):
        super(ModelNew, self).__init__()
        self.linear = nn.Linear(input_size, output_size)
        self.divisor = divisor
        self.fused = fused_module

    def forward(self, x):
        weight = self.linear.weight
        bias = self.linear.bias
        divisor_t = torch.tensor(self.divisor, dtype=x.dtype, device=x.device)
        return self.fused.fused_linear_hip(x, weight, bias, divisor_t)

