fused_post_cpp = """
#include &lt;hip/hip_runtime.h&gt;
#include &lt;torch/extension.h&gt;
#include &lt;cmath&gt;

__global__ void fused_post_kernel(const float *x, const float *bias, float scale, float *out, size_t size, size_t stride_hw, int64_t C) {
    size_t idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx &gt;= size) return;
    int64_t c = static_cast&lt;int64_t&gt;(idx / stride_hw) % C;
    float val = tanhf(x[idx]);
    out[idx] = val * scale + bias[c];
}

torch::Tensor fused_post_hip(torch::Tensor x, torch::Tensor bias, float scale) {
    auto out = torch::empty_like(x);
    int64_t B = x.size(0);
    int64_t C = x.size(1);
    int64_t H = x.size(2);
    int64_t W = x.size(3);
    int64_t total_size = x.numel();
    size_t stride_hw = static_cast&lt;size_t&gt;(H) * static_cast&lt;size_t&gt;(W);
    const int block_size = 256;
    int grid_size = (total_size + block_size - 1) / block_size;
    fused_post_kernel&lt;&lt;&lt;grid_size, block_size&gt;&gt;&gt;(x.data_ptr&lt;float&gt;(), bias.data_ptr&lt;float&gt;(), scale, out.data_ptr&lt;float&gt;(), total_size, stride_hw, C);
    return out;
}
"""

fused_post = load_inline(
    name="fused_post",
    cpp_sources=fused_post_cpp,
    functions=["fused_post_hip"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, scaling_factor, bias_shape, pool_kernel_size):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.scaling_factor = scaling_factor
        self.bias = nn.Parameter(torch.randn(bias_shape))
        self.max_pool = nn.MaxPool2d(pool_kernel_size)
        self.fused_post = fused_post

    def forward(self, x):
        x = self.conv(x)
        x = self.fused_post.fused_post_hip(x, self.bias, float(self.scaling_factor))
        x = self.max_pool(x)
        return x

