    float divv = divisor.item<float>();
    const int threads = 256;
    const int blocks = (B * O + threads - 1) / threads;
    fused_matmul_bias_div_gelu_kernel<<<blocks, threads>>> (
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
