#include &lt;hip/hip_runtime.h&gt;
#include &lt;cfloat&gt;
#include &lt;cmath&gt;

__constant__ float SQRT_1_OVER_2 = 0.70710678118654752440f;
__constant__ float NEG_INF = -3.4028234663852886e+38f;

__global__ void fused_postprocess_kernel(const float *input, float *output, const float scale, const int pool_k, const int out_features, const int batch_size) {
    const int b = blockIdx.x;
    if (b &gt;= batch_size) return;
    const int F = out_features;
    const int num_groups = F / pool_k;
    extern __shared__ float shared_max[];
    const int tid = threadIdx.x;
    float my_max = NEG_INF;
    if (tid &lt; num_groups) {
        float sum_val = 0.0f;
        const int base_idx = b * F + tid * pool_k;
        #pragma unroll 16
        for (int i = 0; i &lt; pool_k; ++i) {
            sum_val += __ldg(input + base_idx + i);
        }
        const float avg = sum_val / static_cast&lt;float&gt;(pool_k);
        const float cd f = 0.5f * (1.0f + erf(avg * SQRT_1_OVER_2));
        const float gelu = avg * cdf;
        const float scaled_val = gelu * scale;
        shared_max[tid] = scaled_val;
        my_max = scaled_val;
    }
    __syncthreads();
    // Tree reduction for max
    for (int s = num_groups / 2; s &gt; 0; s &gt;&gt; =1) {
        if (tid &lt; s) {
            shared_max[tid] = fmaxf(shared_max[tid], shared_max[tid + s]);
        }
        __syncthreads();
    }
    if (tid == 0) {
        output[b] = shared_max[0];
    }
}

