post_conv_cpp = cpp_source + """
std::tuple&lt;torch::Tensor, torch::Tensor&gt; compute_channel_stats_hip(torch::Tensor input) {
  auto sizes = input.sizes();
  int64_t B = sizes[0];
  int64_t C = sizes[1];
  int64_t H = sizes[2];
  int64_t W = sizes[3];
  int64_t pos_size = H * W;
  int64_t total_size = B * C * pos_size;
  auto options = input.options();
  auto sums = torch::zeros({C}, options);
  auto sumsq = torch::zeros({C}, options);
  const int block_size = 256;
  dim3 block(block_size);
  dim3 grid((total_size + block_size - 1LL) / block_size);
  channel_stats_kernel&lt;&lt;&lt;grid, block&gt;&gt;&gt;(input.data_ptr&lt;float&gt;(), sums.data_ptr&lt;float&gt;(), sumsq.data_ptr&lt;float&gt;(), (int)B, (int)C, (int)H, (int)W);
  return std::make_tuple(sums, sumsq);
}

torch::Tensor norm_scale_hip(torch::Tensor input, torch::Tensor means, torch::Tensor stds, torch::Tensor scales) {
  auto sizes = input.sizes();
  int64_t B = sizes[0];
  int64_t C = sizes[1];
  int64_t H = sizes[2];
  int64_t W = sizes[3];
  int64_t G = means.numel();
  int group_size = static_cast&lt;int&gt;(C / G);
  auto out = torch::empty_like(input);
  int pos_size = H * W;
  int64_t total_size = B * C * pos_size;
  const int block_size = 256;
  dim3 block(block_size);
  dim3 grid((total_size + block_size - 1LL) / block_size);
  norm_scale_kernel&lt;&lt;&lt;grid, block&gt;&gt;&gt;(input.data_ptr&lt;float&gt;(), out.data_ptr&lt;float&gt;(), means.data_ptr&lt;float&gt;(), stds.data_ptr&lt;float&gt;(), scales.data_ptr&lt;float&gt;(), (int)B, (int)C, (int)H, (int)W, group_size);
  return out;
}

torch::Tensor maxpool_clamp_hip(torch::Tensor input, float clamp_min, float clamp_max, int kernel_size) {
  auto sizes = input.sizes();
  int64_t B = sizes[0];
  int64_t C = sizes[1];
  int64_t Hin = sizes[2];
  int64_t Win = sizes[3];
  int ks = kernel_size;
  int stride = ks;
  int64_t Hout = (Hin - ks) / stride + 1;
  int64_t Wout = (Win - ks) / stride + 1;
  auto out = torch::zeros({B, C, Hout, Wout}, input.options());
  int64_t posout_size = Hout * Wout;
  int64_t total_out = B * C * posout_size;
  const int block_size = 256;
  dim3 block(block_size);
  dim3 grid((total_out + block_size - 1LL) / block_size);
  maxpool_clamp_kernel&lt;&lt;&lt;grid, block&gt;&gt;&gt;(input.data_ptr&lt;float&gt;(), out.data_ptr&lt;float&gt;(), clamp_min, clamp_max, (int)B, (int)C, (int)Hin, (int)Win, ks);
  return out;
}
"""

custom_ops = load_inline(
    name="post_conv_ops",
    cpp_sources=post_conv_cpp,
    functions=["compute_channel_stats_hip", "norm_scale_hip", "maxpool_clamp_hip"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, num_groups, scale_shape, maxpool_kernel_size, clamp_min, clamp_max):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.scale = nn.Parameter(torch.ones(scale_shape))
        self.out_channels = out_channels
        self.num_groups = num_groups
        self.maxpool_kernel_size = maxpool_kernel_size
        self.clamp_min = clamp_min
        self.clamp_max = clamp_max
        self.custom_ops = custom_ops

    def forward(self, x):
        x = self.conv(x)
        B, C, H, W = x.shape
        sums, sumsq = self.custom_ops.compute_channel_stats_hip(x)
        gs = self.out_channels // self.num_groups
        num_g = self.num_groups
        device = x.device
        dtype = x.dtype
        group_sums = torch.zeros(num_g, dtype=dtype, device=device)
        group_sumsq = torch.zeros(num_g, dtype=dtype, device=device)
        for g in range(num_g):
            s_start = g * gs
            s_end = (g + 1) * gs
            group_sums[g] = sums[s_start:s_end].sum()
            group_sumsq[g] = sumsq[s_start:s_end].sum()
        num_pos = float(B * H * W)
        gs_f = float(gs)
        means = group_sums / (gs_f * num_pos)
        temp_var = group_sumsq / (gs_f * num_pos) - means * means
        vars_ = temp_var + 1e-5
        stds = torch.sqrt(vars_)
        scales_f = self.scale.reshape(-1)
        x = self.custom_ops.norm_scale_hip(x, means, stds, scales_f)
        x = self.custom_ops.maxpool_clamp_hip(x, self.clamp_min, self.clamp_max, self.maxpool_kernel_size)
        return x

