  // normalize
  int64_t norm_grid_size = (B * D + 255LL) / 256LL;
  dim3 grid_norm((unsigned int)norm_grid_size);
  dim3 block_norm(256);
  hipLaunchKernelGGL(softmax_normalize_kernel, grid_norm, block_norm, 0, 0, out.data_ptr<float>(), sumexps.data_ptr<float>(), (int)B, (int)D);
  return out;
}
