fused_post_cpp = """
#include <hip/hip_runtime.h>
#include <cfloat>
#include <cmath>

__constant__ float SQRT_1_OVER_2 = 0.70710678118654752440f;
__constant__ float NEG_INF = -3.402823466e+38f;

__global__ void fused_postprocess_kernel(const float *input, float *output, const float scale, const int pool_k, const int out_features, const int batch_size) {
    const int b = blockIdx.x;
    if (b >= batch_size) return;
    const int F = out_features;
    const int num_groups = F / pool_k;
    extern __shared__ float shared_max[];
    const int tid = threadIdx.x;
    if (tid < num_groups) {
        float sum_val = 0.0f;
        const int base_idx = b * F + tid * pool_k;
        #pragma unroll
        for (int i = 0; i < pool_k; ++i) {
            sum_val += __ldg(input + base_idx + i);
        }
        const float avg = sum_val / static_cast<float>(pool_k);
        const float cdf = 0.5f * (1.0f + erf(avg * SQRT_1_OVER_2));
        const float gelu = avg * cdf;
        const float scaled_val = gelu * scale;
        shared_max[tid] = scaled_val;
    }
    __syncthreads();
    // Tree reduction for max
    for (int s = num_groups / 2; s > 0; s >>= 1) {
        if (tid < s) {
            shared_max[tid] = fmaxf(shared_max[tid], shared_max[tid + s]);
        }
        __syncthreads();
    }
    if (tid == 0) {
        output[b] = shared_max[0];
    }
}

torch::Tensor fused_postprocess_hip(torch::Tensor input, float scale_factor, int pool_kernel_size) {
    const auto batch_sz = input.size(0);
    const auto feat_sz = input.size(1);
    const int n_groups = feat_sz / pool_kernel_size;
    auto output = torch::empty({batch_sz}, input.options());
    dim3 blocks(batch_sz);
    dim3 threads(n_groups);
    const size_t shared_mem_bytes = n_groups * sizeof(float);
    hipLaunchKernelGGL(
        HIP_KERNEL_NAME(fused_postprocess_kernel),
        blocks,
        threads,
        shared_mem_bytes,
        0,
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        scale_factor,
        pool_kernel_size,
        feat_sz,
        batch_sz
    );
    return output;
}
"""

