  const int block_size = 256;
  int64_t total_size = B * M;
  int grid_size = (total_size + block_size - 1) / block_size;
  fused_naive<<<grid_size, block_size>>>(x.data_ptr<float>(), weight.data_ptr<float>(), bias.data_ptr<float>(), scale, out.data_ptr<float>(), (int)B, (int)M, (int)K);
