#include <hip/hip_runtime.h>
#include <torch/extension.h>

__device__ float sigmoid(float x) {
  if (x > 40.0f) return 1.0f;
  if (x < -40.0f) return 0.0f;
  return 1.0f / (1.0f + expf(-x));
}

__global__ void compute_partial_sums_sumsq_kernel(const float* tmp, const float* bias, int B, int C, int rpb, float* p_sum, float* p_sumsq) {
  const int chans_per_block = 256;
  int num_chan_blocks = (C + chans_per_block - 1) / chans_per_block;
  int block_id = blockIdx.x;
  int partial_idx = block_id / num_chan_blocks;
  int chan_block_idx = block_id % num_chan_blocks;
  int chan_start = chan_block_idx * chans_per_block;
  int tid = threadIdx.x;
  int ch = chan_start + tid;
  if (ch >= C) return;
  float bval = bias[ch];
  int row_start = partial_idx * rpb;
  int row_end = min(row_start + rpb, B);
  float sumc = 0.0f;
  float sumsqc = 0.0f;
  for (int row = row_start; row < row_end; row++) {
    float tval = tmp[row * C + ch];
    float sig = sigmoid(tval);
    float raw = sig * tval + bval;
    sumc += raw;
    sumsqc += raw * raw;
  }
  p_sum[partial_idx * C + ch] = sumc;
  p_sumsq[partial_idx * C + ch] = sumsqc;
}

torch::Tensor compute_partials_hip(torch::Tensor tmp, torch::Tensor bias, int64_t B, int64_t C, int64_t rpb, torch::Tensor p_sum, torch::Tensor p_sumsq) {
  auto stream = at::cuda::getCurrentCUDAStream();
  const int chans_per_block = 256;
  int num_chan_blocks = (C + chans_per_block - 1) / chans_per_block;
  int64_t num_partials = (B + rpb - 1LL) / rpb;
  dim3 block(chans_per_block);
  dim3 grid(num_partials * num_chan_blocks);
  compute_partial_sums_sumsq_kernel<<<grid, block, 0, stream>>>(
    tmp.data_ptr<float>(), bias.data_ptr<float>(), (int)B, (int)C, (int)rpb,
    p_sum.data_ptr<float>(), p_sumsq.data_ptr<float>());
  return {};
}

__global__ void reduce_partials_kernel(const float* partial, int num_rows, int C, int rpb, float* final_out) {
  const int chans_per_block = 256;
  int num_chan_blocks = (C + chans_per_block - 1) / chans_per_block;
  int block_id = blockIdx.x;
  int partial_idx = block_id / num_chan_blocks;
  int chan_block_idx = block_id % num_chan_blocks;
  int chan_start = chan_block_idx * chans_per_block;
  int tid = threadIdx.x;
  int ch = chan_start + tid;
  if (ch >= C) return;
  int row_start = partial_idx * rpb;
  int row_end = min(row_start + rpb, num_rows);
  float sumc = 0.0f;
  for (int row = row_start; row < row_end; row++) {
    sumc += partial[row * C + ch];
  }
  final_out[partial_idx * C + ch] = sumc;
}

torch::Tensor reduce_partials_hip(torch::Tensor partial, int64_t num_rows, int64_t C, torch::Tensor final_out) {
  auto stream = at::cuda::getCurrentCUDAStream();
  const int chans_per_block = 256;
  int num_chan_blocks = (C + chans_per_block - 1) / chans_per_block;
  const int rpb = 256;
  int num_partials2 = (num_rows + rpb - 1LL) / rpb;
  dim3 block(chans_per_block);
  dim3 grid(num_partials2 * num_chan_blocks);
  reduce_partials_kernel<<<grid, block, 0, stream>>>(
    partial.data_ptr<float>(), (int)num_rows, (int)C, rpb,
    final_out.data_ptr<float>());
  return {};
}

__global__ void normalize_kernel(const float* tmp, const float* bias, const float* group_means, const float* group_invstd, const float* norm_w, const float* norm_b, int B, int C, int num_groups, int gs, int rpb, float* out) {
  const int chans_per_block = 256;
  int num_chan_blocks = (C + chans_per_block - 1) / chans_per_block;
  int block_id = blockIdx.x;
  int partial_idx = block_id / num_chan_blocks;
  int chan_block_idx = block_id % num_chan_blocks;
  int chan_start = chan_block_idx * chans_per_block;
  int tid = threadIdx.x;
  int ch = chan_start + tid;
  if (ch >= C) return;
  float bval = bias[ch];
  int g = ch / gs;
  float mean_g = group_means[g];
  float invstd_g = group_invstd[g];
  float w = norm_w[ch];
  float nb = norm_b[ch];
  int row_start = partial_idx * rpb;
  int row_end = min(row_start + rpb, B);
  for (int row = row_start; row < row_end; row++) {
    float tval = tmp[row * C + ch];
    float sig = sigmoid(tval);
    float raw = sig * tval + bval;
    float centered = raw - mean_g;
    float normed = centered * invstd_g * w + nb;
    out[row * C + ch] = normed;
  }
}

torch::Tensor normalize_hip(torch::Tensor tmp, torch::Tensor bias, torch::Tensor group_means, torch::Tensor group_invstd, torch::Tensor norm_w, torch::Tensor norm_b, int64_t B, int64_t C, int64_t num_groups, int64_t gs, int64_t rpb, torch::Tensor out) {
