  int64_t num_partials = (B + rpb - 1LL) / rpb;
  dim3 block(chans_per_block);
  dim3 grid(num_partials * num_chan_blocks);
  normalize_kernel<<<grid, block, 0, stream>>>(
    tmp.data_ptr<float>(), bias.data_ptr<float>(), group_means.data_ptr<float>(), group_invstd.data_ptr<float>(),
    norm_w.data_ptr<float>(), norm_b.data_ptr<float>(),
    (int)B, (int)C, (int)num_groups, (int)gs, (int)rpb,
    out.data_ptr<float>());
