"""

class ModelNew(nn.Module):
    def __init__(self, in_features, out_features, num_groups, bias_shape):
        super(ModelNew, self).__init__()
        self.matmul = nn.Linear(in_features, out_features)
        self.bias = nn.Parameter(torch.randn(bias_shape))
        self.group_norm = nn.GroupNorm(num_groups, out_features)
        self.num_groups = num_groups
        self.out_features = out_features
        self.eps = 1e-5
        self.rpb = 256
        self.fused_post = load_inline(
            name="fused_post_ops",
            cpp_sources=cpp_source,
            functions=["compute_partials_hip", "reduce_partials_hip", "normalize_hip"],
            verbose=True,
        )

    def forward(self, x):
        x1 = self.matmul(x)
        B, C = x1.shape
        gs = C // self.num_groups
        rpb = self.rpb
        num_partials = (B + rpb - 1) // rpb
        p_sum = torch.empty(num_partials * C, dtype=torch.float32, device=x.device)
        p_sumsq = torch.empty(num_partials * C, dtype=torch.float32, device=x.device)
        self.fused_post.compute_partials_hip(x1, self.bias, B, C, rpb, p_sum, p_sumsq)
        final_sum = torch.empty(C, dtype=torch.float32, device=x.device)
        final_sumsq = torch.empty(C, dtype=torch.float32, device=x.device)
        self.fused_post.reduce_partials_hip(p_sum, num_partials, C, final_sum)
        self.fused_post.reduce_partials_hip(p_sumsq, num_partials, C, final_sumsq)
        group_means = torch.zeros(self.num_groups, dtype=torch.float32, device=x.device)
        group_vars = torch.zeros(self.num_groups, dtype=torch.float32, device=x.device)
        nelem_g = B * gs
        for g in range(self.num_groups):
            s_ch = g * gs
            e_ch = (g + 1) * gs
            sum_g = torch.sum(final_sum[s_ch:e_ch])
            sumsq_g = torch.sum(final_sumsq[s_ch:e_ch])
            mean_g = sum_g / nelem_g
