#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <tuple>
#include <cmath>

__global__ void channel_stats_kernel(const float *input, float *sums, float *sumsq, int B, int C, int H, int W) {
    int pos_size = H * W;
    int total_size = B * C * pos_size;
    size_t idx = static_cast<size_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    if (idx >= static_cast<size_t>(total_size)) return;
    int bchw = static_cast<int>(idx / pos_size);
    int c = bchw % C;
    float val = input[idx];
    atomicAdd(sums + c, val);
    atomicAdd(sumsq + c, val * val);
}

__global__ void norm_scale_kernel(const float *input, float *output, const float *means, const float *stds, const float *scales, int B, int C, int H, int W, int group_size) {
    int pos_size = H * W;
    int total_size = B * C * pos_size;
    size_t idx = static_cast<size_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    if (idx >= static_cast<size_t>(total_size)) return;
    int bchw = static_cast<int>(idx / pos_size);
    int c = bchw % C;
    int g = c / group_size;
    float m = means[g];
    float s = stds[g];
    float sc = scales[c];
    output[idx] = (input[idx] - m) / s * sc;
}

__global__ void maxpool_clamp_kernel(const float *input, float *output, float cmin, float cmax, int B, int C, int Hin, int Win, int ks) {
    int stride = ks;
    int Hout = (Hin - ks) / stride + 1;
    int Wout = (Win - ks) / stride + 1;
    int posout_size = Hout * Wout;
    int total_out = B * C * posout_size;
    size_t idx = static_cast<size_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    if (idx >= static_cast<size_t>(total_out)) return;
    int bc = static_cast<int>(idx / posout_size);
    int b = bc / C;
    int c = bc % C;
    int hw = static_cast<int>(idx % posout_size);
    int hout = hw / Wout;
    int wout = hw % Wout;
    float mval = -1e20f;
    for (int di = 0; di < ks; di++) {
        int hi = hout * stride + di;
        if (hi >= Hin) continue;
        for (int dj = 0; dj < ks; dj++) {
            int wi = wout * stride + dj;
            if (wi >= Win) continue;
            int idxin = ((b * C + c) * Hin + hi) * Win + wi;
            mval = fmaxf(mval, input[idxin]);
        }
    }
    output[idx] = fmaxf(cmin, fminf(cmax, mval));
}

std::tuple<torch::Tensor, torch::Tensor> compute_channel_stats_hip(torch::Tensor input) {
  auto sizes = input.sizes();
  int64_t B = sizes[0];
  int64_t C = sizes[1];
  int64_t H = sizes[2];
  int64_t W = sizes[3];
  int64_t pos_size = H * W;
  int64_t total_size = B * C * pos_size;
  auto options = input.options();
  auto sums = torch::zeros({C}, options);
  auto sumsq = torch::zeros({C}, options);
  const int block_size = 256;
  dim3 block(block_size);
  dim3 grid(static_cast<unsigned int>((total_size + block_size - 1) / block_size));
  hipLaunchKernelGGL(channel_stats_kernel, grid, block, 0, 0, input.data_ptr<float>(), sums.data_ptr<float>(), sumsq.data_ptr<float>(), static_cast<int>(B), static_cast<int>(C), static_cast<int>(H), static_cast<int>(W));
  return std::make_tuple(sums, sumsq);
}

torch::Tensor norm_scale_hip(torch::Tensor input, torch::Tensor means, torch::Tensor stds, torch::Tensor scales) {
  auto sizes = input.sizes();
  int64_t B = sizes[0];
  int64_t C = sizes[1];
  int64_t H = sizes[2];
  int64_t W = sizes[3];
  int64_t G = means.numel();
  int group_size = static_cast<int>(C / G);
  auto out = torch::empty_like(input);
  int64_t pos_size = H * W;
  int64_t total_size = B * C * pos_size;
  const int block_size = 256;
  dim3 block(block_size);
  dim3 grid(static_cast<unsigned int>((total_size + block_size - 1) / block_size));
  hipLaunchKernelGGL(norm_scale_kernel, grid, block, 0, 0, input.data_ptr<float>(), out.data_ptr<float>(), means.data_ptr<float>(), stds.data_ptr<float>(), scales.data_ptr<float>(), static_cast<int>(B), static_cast<int>(C), static_cast<int>(H), static_cast<int>(W), group_size);
  return out;
}

torch::Tensor maxpool_clamp_hip(torch::Tensor input, float clamp_min, float clamp_max, int kernel_size) {
  auto sizes = input.sizes();
  int64_t B = sizes[0];
  int64_t C = sizes[1];
  int64_t Hin = sizes[2];
  int64_t Win = sizes[3];
  int ks = kernel_size;
  int stride_ = ks;
  int64_t Hout = (Hin - ks) / stride_ + 1;
  int64_t Wout = (Win - ks) / stride_ + 1;
  std::vector<int64_t> out_shape = {B, C, Hout, Wout};
  auto out = torch::zeros(torch::IntArrayRef(out_shape), input.options());
  int64_t posout_size = Hout * Wout;
  int64_t total_out = B * C * posout_size;
  const int block_size = 256;
  dim3 block(block_size);
  dim3 grid(static_cast<unsigned int>((total_out + block_size - 1) / block_size));
  hipLaunchKernelGGL(maxpool_clamp_kernel, grid, block, 0, 0, input.data_ptr<float>(), out.data_ptr<float>(), clamp_min, clamp_max, static_cast<int>(B), static_cast<int>(C), static_cast<int>(Hin), static_cast<int>(Win), ks);
  return out;
}
"""

