class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, num_groups, scale_shape, maxpool_kernel_size, clamp_min, clamp_max):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.scale = nn.Parameter(torch.ones(scale_shape))
        self.out_channels = out_channels
        self.num_groups = num_groups
        self.maxpool_kernel_size = maxpool_kernel_size
        self.clamp_min = clamp_min
        self.clamp_max = clamp_max
        self.custom_ops = custom_ops

    def forward(self, x):
        x = self.conv(x)
        B, C, H, W = x.shape
        sums, sumsq = self.custom_ops.compute_channel_stats_hip(x)
        gs = self.out_channels // self.num_groups
        num_g = self.num_groups
        device = x.device
        dtype = x.dtype
        group_sums = torch.zeros(num_g, dtype=dtype, device=device)
        group_sumsq = torch.zeros(num_g, dtype=dtype, device=device)
        for g in range(num_g):
            s_start = g * gs
            s_end = (g + 1) * gs
            group_sums[g] = sums[s_start:s_end].sum()
            group_sumsq[g] = sumsq[s_start:s_end].sum()
        num_pos = float(B * H * W)
        gs_f = float(gs)
        means = group_sums / (gs_f * num_pos)
        temp_var = group_sumsq / (gs_f * num_pos) - means * means
        vars_ = temp_var + 1e-5
        stds = torch.sqrt(vars_)
        scales_f = self.scale.reshape(-1)
        x = self.custom_ops.norm_scale_hip(x, means, stds, scales_f)
        x = self.custom_ops.maxpool_clamp_hip(x, self.clamp_min, self.clamp_max, self.maxpool_kernel_size)
        return x

