    int ch_offset = n * C + c;
    int row_offset = ch_offset * Hi + base_h;
    sum += tanhf(in[row_offset * Wi + base_w]);
    sum += tanhf(in[(row_offset + 1) * Wi + base_w]);
    sum += tanhf(in[row_offset * Wi + base_w + 1]);
    sum += tanhf(in[(row_offset + 1) * Wi + base_w + 1]);
    out[gid] = sum * 0.25f - sub_val;
