conv2d_cpp_source = """
#include <hip/hip_runtime.h>

__global__ void conv2d_kernel(const float* input, const float* weight, const float* bias, float* output,
                              int N, int Cin, int Cout, int H, int W, int K, int Hout, int Wout, int RS, int CS, int TSX, int TSY) {
  extern __shared__ float shared[];
  int tx = threadIdx.x;
  int ty = threadIdx.y;
  int tid = tx + ty * blockDim.x;
  int wout = blockIdx.x * TSX + tx;
  int hout = blockIdx.y * TSY + ty;
  int bco = blockIdx.z;
  int n = bco / Cout;
  int cout = bco % Cout;

  if (hout < Hout && wout < Wout && n < N) {
    // Load input tile to shared memory
    int tile_r_start = blockIdx.y * TSY;
    int tile_c_start = blockIdx.x * TSX;
    for (int idx = tid; idx < Cin * RS * CS; idx += blockDim.x * blockDim.y) {
      int cin_load = idx / (RS * CS);
      int off = idx % (RS * CS);
      int r = off / CS;
      int c = off % CS;
      int hin = tile_r_start + r;
      int win = tile_c_start + c;
      float val = 0.0f;
      if (cin_load < Cin && hin >= 0 && hin < H && win >= 0 && win < W) {
        val = input[n * (Cin * H * W) + cin_load * (H * W) + hin * W + win];
      }
      shared[idx] = val;
    }
    __syncthreads();

    // Compute convolution
    float sum = bias[cout];
    for (int cin = 0; cin < Cin; ++cin) {
      for (int dy = 0; dy < K; ++dy) {
        int r = ty + dy;
        for (int dx = 0; dx < K; ++dx) {
          int c = tx + dx;
          if (r < RS && c < CS) {
            sum += shared[cin * (RS * CS) + r * CS + c] * weight[cout * (Cin * K * K) + cin * (K * K) + dy * K + dx];
          }
        }
      }
    }
    output[n * (Cout * Hout * Wout) + cout * (Hout * Wout) + hout * Wout + wout] = sum;
  }
}

torch::Tensor conv2d_hip(torch::Tensor input, torch::Tensor weight, torch::Tensor bias, int K) {
  auto N_ = input.size(0);
  auto Cin_ = input.size(1);
  auto H_ = input.size(2);
  auto W_ = input.size(3);
  auto Cout_ = weight.size(0);
  auto Hout_ = H_ - K + 1;
  auto Wout_ = W_ - K + 1;
  int N = static_cast<int>(N_);
  int Cin = static_cast<int>(Cin_);
  int H = static_cast<int>(H_);
  int W = static_cast<int>(W_);
  int Cout = static_cast<int>(Cout_);
  int Hout = static_cast<int>(Hout_);
  int Wout = static_cast<int>(Wout_);
  auto output = torch::empty({N_, Cout_, Hout_, Wout_}, input.options());
  const int TSX = 16;
  const int TSY = 16;
  int halo = K - 1;
  int RS = TSY + halo;
  int CS = TSX + halo;
  dim3 block(TSX, TSY);
  dim3 grid((Wout + TSX - 1) / TSX, (Hout + TSY - 1) / TSY, N * Cout);
  size_t shared_size = (size_t)Cin * RS * CS * sizeof(float);
  conv2d_kernel<<<grid, block, shared_size>>>(input.data_ptr<float>(), weight.data_ptr<float>(), bias.data_ptr<float>(), output.data_ptr<float>(),
                                               N, Cin, Cout, H, W, K, Hout, Wout, RS, CS, TSX, TSY);
  return output;
}
"""

custom_conv = load_inline(
    name="conv2d",
    cpp_sources=conv2d_cpp_source,
    functions=["conv2d_hip"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, scaling_factor):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.bn = nn.BatchNorm2d(out_channels)
        self.scaling_factor = scaling_factor
        self.K = kernel_size
        self.custom_conv = custom_conv

    def forward(self, x):
        weight = self.conv.weight
        bias = self.conv.bias
        conv_out = self.custom_conv.conv2d_hip(x, weight, bias, self.K)
        x = self.bn(conv_out)
        return x * self.scaling_factor

