                if(xi >= W_in) continue;
                long long ii = ((1LL * b * C + c) * D_in + zi) * H_in + yi;
                ii = ii * W_in + xi;
                float val = input[ii];
                if(val > mval) mval = val;
            }
        }
    }
    long long oi = ((1LL * b * C + c) * D_out + z) * H_out + y;
    oi = oi * W_out + x;
    output[oi] = mval;
}

