fused_cpp = """
#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <cmath>

__global__ void fused_naive(const float* x, const float* w, const float* bias, float scale, float* out, int B, int M, int K) {
  int idx = blockIdx.x * blockDim.x + threadIdx.x;
  if (idx >= B * M) return;
  int b = idx / M;
  int m = idx % M;
  float sum = bias[m];
  for (int k = 0; k < K; ++k) {
    sum += x[b * K + k] * w[m * K + k];
  }
  float sigmoid = 1.0f / (1.0f + expf(-sum));
  out[b * M + m] = sum * sigmoid * scale;
}

torch::Tensor fused_matmul_swish_hip(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, float scale) {
  int64_t B = x.size(0);
  int64_t K = x.size(1);
  int64_t M = weight.size(0);
  auto out = torch::empty({B, M}, x.options());
  const int block_size = 256;
  int64_t total_size = B * M;
  int grid_size = (total_size + block_size - 1) / block_size;
  fused_naive<<<grid_size, block_size>>>(x.data_ptr<float>(), weight.data_ptr<float>(), bias.data_ptr<float>(), scale, out.data_ptr<float>(), (int)B, (int)M, (int)K);
  return out;
}
"""

fused = load_inline(
    name="fused",
    cpp_sources=fused_cpp,
    functions=["fused_matmul_swish_hip"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self, in_features, out_features, scaling_factor):
        super(ModelNew, self).__init__()
        self.in_features = in_features
        self.out_features = out_features
        self.scaling_factor = scaling_factor
        self.weight = nn.Parameter(torch.empty((out_features, in_features), dtype=torch.float32))
        self.bias = nn.Parameter(torch.empty((out_features, ), dtype=torch.float32))
        self.reset_parameters()

    def reset_parameters(self) -> None:
        nninit.kaiming_uniform_(self.weight, a=math.sqrt(5))
        fan_in, _ = nninit._calculate_fan_in_and_fan_out(self.weight)
        bound = 1 / math.sqrt(fan_in) if fan_in > 0 else 0
        nninit.uniform_(self.bias, -bound, bound)

    def forward(self, x):
        return fused.fused_matmul_swish_hip(x, self.weight, self.bias, float(self.scaling_factor))

