#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <limits>
#include <cmath>
#include <cfloat>

__device__ float gelu(float x) {
  return 0.5f * x * (1.0f + erf(0.7071067811865475f * x));
}

__global__ void gelu_max_reduce_kernel(const float *input, float *temp_maxs, int B, int D, int blocks_per_row) {
  const int BS = 1024;
  int tid = threadIdx.x;
  int bid = blockIdx.x;
  int b = bid / blocks_per_row;
  int bo = bid % blocks_per_row;
  int j = bo * BS + tid;
  float val = -FLT_MAX;
  if (b < B && j < D) {
    val = gelu(input[b * D + j]);
  }
  extern __shared__ float sdata[];
  sdata[tid] = val;
  __syncthreads();
  for (int s = 512; s > 0; s >>= 1) {
    if (tid < s) {
      sdata[tid] = fmaxf(sdata[tid], sdata[tid + s]);
    }
    __syncthreads();
  }
  if (tid == 0) {
    temp_maxs[b * blocks_per_row + bo] = sdata[0];
  }
}

__global__ void row_max_reduce_kernel(const float *temp_maxs, float *max_out, int B, int blocks_per_row) {
  int tid = blockIdx.x * blockDim.x + threadIdx.x;
  if (tid < B) {
    float mx = temp_maxs[tid * blocks_per_row];
    for (int k = 1; k < blocks_per_row; ++k) {
      mx = fmaxf(mx, temp_maxs[tid * blocks_per_row + k]);
    }
    max_out[tid] = mx;
  }
}

__global__ void gelu_exp_sum_kernel(const float *input, const float *maxv, float *out, float *sumexp, int B, int D, int blocks_per_row) {
  const int BS = 1024;
  int tid = threadIdx.x;
  int bid = blockIdx.x;
  int b = bid / blocks_per_row;
  int bo = bid % blocks_per_row;
  int j = bo * BS + tid;
  float val = 0.0f;
  if (b < B && j < D) {
    float gx = gelu(input[b * D + j]);
    val = expf(gx - maxv[b]);
    out[b * D + j] = val;
  }
  extern __shared__ float sdata[];
  sdata[tid] = val;
  __syncthreads();
  for (int s = 512; s > 0; s >>= 1) {
    if (tid < s) {
      sdata[tid] += sdata[tid + s];
    }
    __syncthreads();
  }
  if (tid == 0) {
    atomicAdd(&sumexp[b], sdata[0]);
  }
}

__global__ void softmax_normalize_kernel(float *out, const float *sumexp, int B, int D) {
  int idx = blockIdx.x * blockDim.x + threadIdx.x;
  if (idx < B * D) {
    int b = idx / D;
    out[idx] /= sumexp[b];
  }
}

torch::Tensor fused_gelu_softmax_hip(torch::Tensor input) {
  torch::Tensor input_ = input.contiguous();
  auto sizes = input_.sizes();
  TORCH_CHECK(sizes.size() == 2, "Expect 2D tensor");
  int64_t B = sizes[0];
  int64_t D = sizes[1];
  auto out = torch::empty_like(input_);
  auto options = torch::TensorOptions().dtype(torch::kFloat32).device(input_.device());
  auto maxv = torch::full({B}, -std::numeric_limits<float>::infinity(), options);
  auto sumexps = torch::zeros({B}, options);
  const int64_t block_size_i = 1024;
  int64_t blocks_per_row = (D + block_size_i - 1) / block_size_i;
  auto temp_maxs = torch::empty({B * blocks_per_row}, options);
  int64_t grid_size = B * blocks_per_row;
  dim3 block(block_size_i);
  dim3 grid1((unsigned int)grid_size);
  size_t shmem = block_size_i * sizeof(float);
  hipLaunchKernelGGL(gelu_max_reduce_kernel, grid1, block, shmem, 0, input_.data_ptr<float>(), temp_maxs.data_ptr<float>(), (int)B, (int)D, (int)blocks_per_row);
  // reduce max
  int64_t reduce_grid = (B + block_size_i - 1LL) / block_size_i;
  dim3 grid_reduce((unsigned int)reduce_grid);
  dim3 block_reduce(block_size_i);
  hipLaunchKernelGGL(row_max_reduce_kernel, grid_reduce, block_reduce, 0, 0, temp_maxs.data_ptr<float>(), maxv.data_ptr<float>(), (int)B, (int)blocks_per_row);
