__global__ void fused_scale_pool_clamp_kernel(const float *input, float *output, const float *scales, float cmin, float cmax, int B, int C, int Hin, int Win, int ks) {
    int stride = ks;
    int Hout = (Hin - ks) / stride + 1;
    int Wout = (Win - ks) / stride + 1;
    int posout_size = Hout * Wout;
    int total_out = B * C * posout_size;
    size_t idx = static_cast<size_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    if (idx >= static_cast<size_t>(total_out)) return;
    int bc = static_cast<int>(idx / posout_size);
    int b = bc / C;
    int c = bc % C;
    int hw = static_cast<int>(idx % posout_size);
    int hout = hw / Wout;
    int wout = hw % Wout;
    float mval = -1e20f;
    float sc = scales[c];
    for (int di = 0; di < ks; di++) {
        int hi = hout * stride + di;
        if (hi >= Hin) continue;
        for (int dj = 0; dj < ks; dj++) {
            int wi = wout * stride + dj;
            if (wi >= Win) continue;
            int idxin = ((b * C + c) * Hin + hi) * Win + wi;
            float scaled = input[idxin] * sc;
            mval = fmaxf(mval, scaled);
        }
    }
    output[idx] = fmaxf(cmin, fminf(cmax, mval));
}

torch::Tensor fused_scale_pool_clamp_hip(torch::Tensor input, torch::Tensor scales, float clamp_min, float clamp_max, int kernel_size) {
  auto sizes = input.sizes();
  int64_t B = sizes[0];
  int64_t C = sizes[1];
  int64_t Hin = sizes[2];
  int64_t Win = sizes[3];
  int ks = kernel_size;
  int stride = ks;
  int64_t Hout = (Hin - ks) / stride + 1;
  int64_t Wout = (Win - ks) / stride + 1;
  auto out = torch::zeros({B, C, Hout, Wout}, input.options());
  int64_t posout_size = Hout * Wout;
  int64_t total_out = B * C * posout_size;
  const int block_size = 256;
  dim3 block(block_size);
  dim3 grid(static_cast<unsigned int>((total_out + block_size - 1LL) / block_size));
  hipLaunchKernelGGL(fused_scale_pool_clamp_kernel, grid, block, 0, 0, input.data_ptr<float>(), out.data_ptr<float>(), scales.data_ptr<float>(), clamp_min, clamp_max, static_cast<int>(B), static_cast<int>(C), static_cast<int>(Hin), static_cast<int>(Win), ks);
  return out;
