    int b = idx / P;
    int p = idx % P;
    int start = p * kernel_size;
    float maxv = y[b * M + start];
    for (int k = 1; k < kernel_size; ++k) {
        maxv = fmaxf(maxv, y[b * M + start + k]);
    }
    pooled[b * P + p] = maxv;
}

