    int B = y.size(0);
    int M = y.size(1);
    int kernel_size = *ks_t.data_ptr<int>();
    int P = M / kernel_size;
    torch::Tensor pooled = torch::empty({B, P}, y.options());
    int total_elems = B * P;
    const int block_size = 256;
    const int grid_size = (total_elems + block_size - 1) / block_size;
    maxpool1d_kernel<<<grid_size, block_size>>>(y.data_ptr<float>(), pooled.data_ptr<float>(), B, M, kernel_size);
    return pooled;
}
