cpp = """
#include <hip/hip_runtime.h>
#include <cmath>

__device__ float gelu_fp32(float x) {
    float x2 = x * x;
    float x3 = x2 * x;
    float d = tanhf(0.7978845608f * (x + 0.044715f * x3));
    return 0.5f * x * (1.0f + d);
}

__global__ void fused_matmul_bias_div_gelu_kernel(
    const float* __restrict__ x, 
    const float* __restrict__ w, 
    const float* __restrict__ b, 
    float div, 
    float* __restrict__ out,
    int B, int I, int O
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int N = B * O;
    if (idx >= N) return;
    int batch = idx / O;
    int row = idx % O;
    float acc = 0.0f;
    const int stride = I;
    int col;
    for (col = 0; col <= I - 4; col += 4) {
        float4 xv = reinterpret_cast<const float4*>(&x[batch * stride + col])[0];
        float4 wv = reinterpret_cast<const float4*>(&w[row * stride + col])[0];
        acc += xv.x * wv.x + xv.y * wv.y + xv.z * wv.z + xv.w * wv.w;
    }
    for (; col < I; col++) {
        acc += x[batch * stride + col] * w[row * stride + col];
    }
    acc += b[row];
    float val = acc / div;
    out[batch * O + row] = gelu_fp32(val);
}

torch::Tensor fused_linear_hip(
