#include <hip/hip_runtime.h>
#include <cmath>

__device__ float gelu_fp32(float x) {
    float x2 = x * x;
    float x3 = x2 * x;
    float d = tanhf(0.7978845608f * (x + 0.044715f * x3));
    return 0.5f * x * (1.0f + d);
}

__global__ void fused_matmul_bias_div_gelu_kernel(
    const float* __restrict__ x, 
    const float* __restrict__ w, 
    const float* __restrict__ b, 
    float div, 
    float* __restrict__ out,
    int B, int I, int O
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int N = B * O;
    if (idx >= N) return;
    int batch = idx / O;
    int row = idx % O;
    float acc = 0.0f;
    const int stride = I;
    for (int col = 0; col < I; ++col) {
        acc += x[batch * stride + col] * w[row * stride + col];
    }
    acc += b[row];
    float val = acc / div;
    out[batch * O + row] = gelu_fp32(val);
}

torch::Tensor fused_linear_hip(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    torch::Tensor divisor
) {
    int B = x.size(0);
    int I = x.size(1);
    int O = weight.size(0);
    auto out = torch::zeros({B, O}, x.options());
    float divv = divisor.item<float>();
    const int threads = 1024;
    const int blocks = (B * O + threads - 1) / threads;
    dim3 grid(blocks);
    dim3 block(threads);
    fused_matmul_bias_div_gelu_kernel<<<grid, block>>> (
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        divv,
        out.data_ptr<float>(),
        B, I, O
    );
    return out;
}
"""

