__global__ void norm_apply_kernel(const float* raw, const float* group_means, const float* group_invstd, const float* norm_w, const float* norm_b, int B, int C, int num_groups, int gs, int rpb, float* out) {
  const int chans_per_block = 256;
  int num_chan_blocks = (C + chans_per_block - 1) / chans_per_block;
  int block_id = blockIdx.x;
  int partial_idx = block_id / num_chan_blocks;
  int chan_block_idx = block_id % num_chan_blocks;
  int chan_start = chan_block_idx * chans_per_block;
  int tid = threadIdx.x;
  int ch = chan_start + tid;
  if (ch >= C) return;
  int g = ch / gs;
  float mean_g = group_means[g];
  float invstd_g = group_invstd[g];
  float w = norm_w[ch];
  float nb = norm_b[ch];
  int row_start = partial_idx * rpb;
  int row_end = row_start + rpb;
  if (row_end > B) row_end = B;
  for (int row = row_start; row < row_end; row++) {
    float raw_val = raw[row * C + ch];
    float centered = raw_val - mean_g;
    float normed = centered * invstd_g * w + nb;
    out[row * C + ch] = normed;
  }
}

torch::Tensor norm_apply_hip(torch::Tensor raw, torch::Tensor group_means, torch::Tensor group_invstd, torch::Tensor norm_w, torch::Tensor norm_b, int64_t B_, int64_t C_, int64_t num_groups_, int64_t gs_, int64_t rpb_, torch::Tensor out) {
  int B = static_cast<int>(B_);
  int C = static_cast<int>(C_);
  int num_groups = static_cast<int>(num_groups_);
  int gs = static_cast<int>(gs_);
  int rpb = static_cast<int>(rpb_);
  const int chans_per_block = 256;
  int num_chan_blocks = (C + chans_per_block - 1) / chans_per_block;
  int64_t num_partials_ = (B_ + rpb_ - 1) / rpb_;
  int num_partials = static_cast<int>(num_partials_);
  dim3 block(chans_per_block);
  dim3 grid(num_partials * num_chan_blocks);
  norm_apply_kernel<<<grid, block>>>(
    raw.data_ptr<float>(), group_means.data_ptr<float>(), group_invstd.data_ptr<float>(),
    norm_w.data_ptr<float>(), norm_b.data_ptr<float>(),
    B, C, num_groups, gs, rpb,
    out.data_ptr<float>());
  return torch::Tensor();
}
