__global__ void fused_norm_scale_pool_clamp_kernel(const float *input, float *output, const float *means, const float *stds, const float *scales, float cmin, float cmax, int B, int C, int Hin, int Win, int ks, int group_size) {
    int stride = ks;
    int Hout = (Hin - ks) / stride + 1;
    int Wout = (Win - ks) / stride + 1;
    int posout_size = Hout * Wout;
    int total_out = B * C * posout_size;
    size_t idx = static_cast<size_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    if (idx >= static_cast<size_t>(total_out)) return;
    int bc = static_cast<int>(idx / posout_size);
    int b = bc / C;
    int c = bc % C;
    int g = c / group_size;
    float m = means[g];
    float s = stds[g];
    float sc = scales[c];
    int hw = static_cast<int>(idx % posout_size);
    int hout = hw / Wout;
    int wout = hw % Wout;
    float mval = -1e20f;
    for (int di = 0; di < ks; di++) {
        int hi = hout * stride + di;
        if (hi >= Hin) continue;
        for (int dj = 0; dj < ks; dj++) {
            int wi = wout * stride + dj;
            if (wi >= Win) continue;
            int idxin = ((b * C + c) * Hin + hi) * Win + wi;
            float normed = (input[idxin] - m) / s * sc;
            mval = fmaxf(mval, normed);
        }
    }
    output[idx] = fmaxf(cmin, fminf(cmax, mval));
}

