class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, num_groups, scale_shape, maxpool_kernel_size, clamp_min, clamp_max):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.scale = nn.Parameter(torch.ones(scale_shape))
        self.out_channels = out_channels
        self.num_groups = num_groups
        self.maxpool_kernel_size = maxpool_kernel_size
        self.clamp_min = clamp_min
        self.clamp_max = clamp_max
        self.custom_ops = custom_ops

    def forward(self, x):
        x = self.conv(x)
        B, C, H, W = x.shape
        sums_c = torch.sum(x, dim=(0, 2, 3))
        sumsq_c = torch.sum(x * x, dim=(0, 2, 3))
        gs = self.out_channels // self.num_groups
        num_g = self.num_groups
        group_sums = torch.zeros(num_g, dtype=x.dtype, device=x.device)
        group_sumsq = torch.zeros(num_g, dtype=x.dtype, device=x.device)
        for g in range(num_g):
            s_start = g * gs
            s_end = (g + 1) * gs
            group_sums[g] = sums_c[s_start:s_end].sum()
            group_sumsq[g] = sumsq_c[s_start:s_end].sum()
        num_pos = B * H * W
        gs_f = float(gs)
        num_pos_f = float(num_pos)
        means = group_sums / (gs_f * num_pos_f)
        temp_var = group_sumsq / (gs_f * num_pos_f) - means * means
        vars_ = temp_var + 1e-5
        stds = torch.sqrt(vars_)
        scales_f = self.scale.reshape(-1)
        x = self.custom_ops.fused_norm_scale_pool_clamp_hip(x, means, stds, scales_f, self.clamp_min, self.clamp_max, self.maxpool_kernel_size, gs)
        return x

