        }
        local_sum += maxv;
    }
    extern __shared__ double sdata[];
    sdata[tid] = local_sum;
    __syncthreads();
    for (int offset = block_size / 2; offset > 0; offset /= 2) {
        if (tid < offset) {
            sdata[tid] += sdata[tid + offset];
        }
        __syncthreads();
    }
    if (tid == 0) {
        out[b] = static_cast<float>(sdata[0]) * scale;
    }
}

