    const int block_size = 256;
    const int grid_size = B;
    size_t shmem_bytes = block_size * sizeof(double);
    fused_pool_sum_scale_kernel<<<grid_size, block_size, shmem_bytes>>>(y.data_ptr<float>(), scale, out.data_ptr<float>(), B, M, kernel_size);
