        bound = 1 / math.sqrt(fan_in) if fan_in > 0 else 0
        torch.nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x):
        x = self.fused.fused_linear_gelu_hip(x, self.weight, self.bias)
        x = F.softmax(x, dim=1)
        return x

