#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <cmath>

#define TILE_N 256
#define TILE_K 16

__global__ void fused_tiled(const float* x, const float* w, const float* bias, float scale, float* out, int B, int M, int K) {
  int b = blockIdx.y;
  if (b >= B) return;
  int tn = threadIdx.x;
  int n_tile = blockIdx.x;
  int n = n_tile * TILE_N + tn;
  if (n >= M) return;
  float acc = bias[n];
  extern __shared__ float sh[];
  float *sh_x = sh;
  float *sh_w = sh + TILE_K;
  int num_tiles = (K + TILE_K - 1) / TILE_K;
  for (int ktile = 0; ktile < num_tiles; ++ktile) {
    int kbase = ktile * TILE_K;
    // load sh_x
    if (tn < TILE_K) {
      int kk = kbase + tn;
      sh_x[tn] = (kk < K) ? x[b * K + kk] : 0.0f;
    }
    __syncthreads();
    // load sh_w
    for (int tk = 0; tk < TILE_K; ++tk) {
      int kk = kbase + tk;
      if (kk < K) {
        sh_w[tk * TILE_N + tn] = w[n * K + kk];
      } else {
        sh_w[tk * TILE_N + tn] = 0.0f;
      }
    }
    __syncthreads();
    // compute
    for (int tk = 0; tk < TILE_K; ++tk) {
      acc += sh_x[tk] * sh_w[tk * TILE_N + tn];
    }
  }
  float sig = 1.0f / (1.0f + __expf(-acc));
  out[b * M + n] = acc * sig * scale;
}

