  auto out = torch::empty({B, M}, x.options());
  dim3 block(TILE_N);
  dim3 grid((M + TILE_N - 1) / TILE_N, (int)B);
  size_t shsize = sizeof(float) * (TILE_K + TILE_K * TILE_N);
  fused_tiled<<<grid, block, shsize>>>(x.data_ptr<float>(), weight.data_ptr<float>(), bias.data_ptr<float>(), scale, out.data_ptr<float>(), (int)B, (int)M, (int)K);
  return out;
}
