os.environ["CXX"] = "hipcc"
import torch
import torch.nn as nn
import torch.nn.init as nninit
import math
from torch.utils.cpp_extension import load_inline

fused_cpp = """
#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <cmath>

#define TILE_N 64
#define TILE_K 64

__global__ void fused_tiled(const float* x, const float* w, const float* bias, float scale, float* out, int B, int M, int K) {
  int b = blockIdx.y;
  if (b >= B) return;
  int tn = threadIdx.x;
  int n_tile = blockIdx.x;
  int n = n_tile * TILE_N + tn;
  if (n >= M) return;
  float acc = bias[n];
  extern __shared__ float sh[];
  float *sh_x = sh;
  float *sh_w = sh + TILE_K;
  int num_tiles = (K + TILE_K - 1) / TILE_K;
  for (int ktile = 0; ktile < num_tiles; ++ktile) {
    int kbase = ktile * TILE_K;
    // load sh_x
    if (tn < TILE_K) {
      int kk = kbase + tn;
      sh_x[tn] = (kk < K) ? x[b * K + kk] : 0.0f;
    }
    __syncthreads();
    // load sh_w
#pragma unroll
    for (int tk = 0; tk < TILE_K; ++tk) {
      int kk = kbase + tk;
      sh_w[tk * TILE_N + tn] = (kk < K) ? w[n * K + kk] : 0.0f;
    }
    __syncthreads();
    // compute
#pragma unroll
    for (int tk = 0; tk < TILE_K; ++tk) {
      acc += sh_x[tk] * sh_w[tk * TILE_N + tn];
    }
  }
  float sig = 1.0f / (1.0f + __expf(-acc));
  out[b * M + n] = acc * sig * scale;
}

torch::Tensor fused_matmul_swish_hip(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, float scale) {
  int64_t B = x.size(0);
  int64_t K = x.size(1);
  int64_t M = weight.size(0);
  auto out = torch::empty({B, M}, x.options());
  dim3 block(TILE_N);
  dim3 grid((M + TILE_N - 1) / TILE_N, (int)B);
  size_t shsize = sizeof(float) * (TILE_K + TILE_K * TILE_N);
  fused_tiled<<<grid, block, shsize>>>(x.data_ptr<float>(), weight.data_ptr<float>(), bias.data_ptr<float>(), scale, out.data_ptr<float>(), (int)B, (int)M, (int)K);
  return out;
}
"""

fused = load_inline(
    name="fused",
    cpp_sources=fused_cpp,
    functions=["fused_matmul_swish_hip"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self, in_features, out_features, scaling_factor):
        super(ModelNew, self).__init__()
        self.in_features = in_features
        self.out_features = out_features
        self.scaling_factor = scaling_factor
        self.weight = nn.Parameter(torch.empty((out_features, in_features), dtype=torch.float32))
        self.bias = nn.Parameter(torch.empty((out_features, ), dtype=torch.float32))
        self.reset_parameters()

    def reset_parameters(self) -> None:
        nninit.kaiming_uniform_(self.weight, a=math.sqrt(5))
        fan_in, _ = nninit._calculate_fan_in_and_fan_out(self.weight)
        bound = 1 / math.sqrt(fan_in) if fan_in > 0 else 0
        nninit.uniform_(self.bias, -bound, bound)

    def forward(self, x):
        return fused.fused_matmul_swish_hip(x, self.weight, self.bias, float(self.scaling_factor))

